// ioBroker object: script.js.common.go-E_V4_Debug
// name: go-E_V4_Debug
// engineType: Blockly
// enabled: True

var datum, txt;

// Beschreibe diese Funktion …
async function Logfile(datum, txt) {
    if (getState('0_userdata.0.go-e_V4.DebugAktiv_V4').val) {
      require('fs').appendFileSync('/opt/iobroker/log/' + datum + ' - go_E_V4.log', formatDate(new Date(), "hh:mm:ss") + " \t" + txt + "\n");}
}


